// android/ is generated by prebuild, so Gradle's speed switches live here instead of in a
// checked-in gradle.properties: the build cache skips work a previous build already did, parallel
// builds use every core, and a bigger heap stops GC thrashing. (No configuration cache: Expo's
// app/build.gradle runs node while configuring, which fails the build when it is on.)
const { withGradleProperties } = require('expo/config-plugins');

const PROPERTIES = {
	'org.gradle.caching': 'true',
	'org.gradle.parallel': 'true',
	'org.gradle.jvmargs': '-Xmx6g -XX:MaxMetaspaceSize=1g -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8',
};

module.exports = function withFastBuilds(config) {
	return withGradleProperties(config, config => {
		for (const [key, value] of Object.entries(PROPERTIES)) {
			const item = config.modResults.find(entry => entry.type === 'property' && entry.key === key);
			if (item) {
				item.value = value;
			} else {
				config.modResults.push({ type: 'property', key, value });
			}
		}
		return config;
	});
};
